package com.bank.raise;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.function.BiFunction;
import java.util.logging.*;

public class BiFunctionDemo {
    private static final Logger log = Logger.getLogger("Raise");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Employee rajesh = new Employee("Rajesh", new BigDecimal("1000000"));
        RaiseService service = new RaiseService();

        Employee raised = service.applyRaise(rajesh, new BigDecimal("10")); // +10%
        log.info(() -> rajesh.getName() + ": " + rajesh.getSalary()
            + " → " + raised.getSalary());
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final BigDecimal salary;
        Employee(String name, BigDecimal salary) { this.name = name;
        this.salary = salary; }
    String getName() { return name; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/RaiseService.java ───
class RaiseService {
    // BiFunction: (employee, raise %) → new employee with raised salary
    private final BiFunction<Employee, BigDecimal, Employee> raise = (e, pct) -> {
        BigDecimal factor = BigDecimal.ONE.add(pct.movePointLeft(2)); // 1 + pct/100
        BigDecimal newSalary = e.getSalary().multiply(factor)
            .setScale(2, RoundingMode.HALF_UP);                       // exact money
        return new Employee(e.getName(), newSalary);                  // immutable: new object
    };

    Employee applyRaise(Employee e, BigDecimal pct) {
        return raise.apply(e, pct);
    }
}
